"Para Esmeralda necesitas una {n}RM estimada de {n} kg. Por ejemplo: {n} kg × {n}.": "باش توصل للزمرد خاصك {n}RM مقدّرة ديال {n} كيلو. مثلا: {n} كيلو × {n}.",
"Para Platino necesitas una {n}RM estimada de {n} kg. Por ejemplo: {n} kg de ayuda × {n}.": "باش توصل للبلاتين خاصك {n}RM مقدّرة ديال {n} كيلو. مثلا: {n} كيلو ديال المساعدة × {n}.",
"Para a la altura del pecho y baja despacio.": "وقف ف علو الصدر ونزل بشوية.",
"Para borrar la cuenta de la nube, vuelve a iniciar sesión.": "باش تمسح الكونط ديالك ف السحابة، دخل عاوتاني.",
"Para continuar, marca la casilla de la política de privacidad.": "باش تكمّل، علّم على الخانة ديال سياسة الخصوصية.",
"Para crear la cuenta, marca la casilla de la política de privacidad.": "باش دير الكونط، علّم على الخانة ديال سياسة الخصوصية.",
"Para ejercicios añadidos a mano. En la rutina, cada ejercicio guarda su propio descanso.": "للتمارين اللي زدتي باليد. ف الروتين، كل تمرين كيحتافظ بوقت الراحة ديالو.",
"Para si notas dolor (el esfuerzo muscular es normal; el dolor articular o punzante, no).": "وقف إلا حسيتي بوجع (المجهود ف العضلة عادي؛ الوجع ف المفاصل ولا الوخز لا).",
"Para subir, mejora tus músculos más flojos: Espalda y Glúteos.": "باش تطلع، حسّن العضلات الضعاف ديالك: الضهر والأرداف.",
"Para tener más datos en este grupo puedes añadir: Curl con mancuernas, Curl martillo, Curl en polea.": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: كورل بالهالتيرات، كورل مارطو، كورل ف البولي.",
"Para tener más datos en este grupo puedes añadir: Curl de muñeca, Curl inverso con barra, Curl de muñeca en polea.": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: كورل المعصم، كورل معكوس بالبارا، كورل المعصم ف البولي.",
"Para tener más datos en este grupo puedes añadir: Dominadas, Jalón al pecho, Remo con barra.": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: العقلة، جبدة للصدر، رامور بالبارا.",
"Para tener más datos en este grupo puedes añadir: Extensión de tríceps en polea, Extensión tras nuca con mancuerna, Tríceps en máquina.": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: ترايسبس ف البولي، إكستونسيون بالهالتير فوق الراس، ترايسبس ف الماشينة.",
"Para tener más datos en este grupo puedes añadir: Gemelos en máquina, Gemelos en prensa, Gemelos en multipower.": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: السمانة ف الماشينة، السمانة ف البريس، السمانة ف السميث.",
"Para tener más datos en este grupo puedes añadir: Patada de glúteo en polea, Abductores en máquina, Pull through en polea.": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: الضربة ديال الأرداف ف البولي، أبدكسيون ف الماشينة، بول ثرو ف البولي.",
"Para tener más datos en este grupo puedes añadir: Press de hombro con mancuernas, Press de hombro en máquina, Elevaciones laterales.": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: بريس الكتاف بالهالتيرات، بريس الكتاف ف الماشينة، إليفاسيون لاطيرال.",
"Para tener más datos en este grupo puedes añadir: Press inclinado con mancuernas, Press de pecho en máquina, Contractora (pec deck).": "باش تزيد الداتا ف هاد المجموعة تقدر تزيد: بريس مايل بالهالتيرات، بريس الصدر ف الماشينة، بيك ديك.",
