"Asas paralelas, palmas mirándose.": "البوانيي متوازيين، الكفوف كيشوفو بعضياتهم.",
"Baja la barra a la parte baja del pecho con los codos pegados al cuerpo.": "نزّل البارا للتحت ديال الصدر والمرافق لاصقين.",
"Coge la barra con las palmas hacia abajo e inclina el tronco con la espalda recta.": "شد البارا والكفوف لتحت وميّل جسمك للقدام وضهرك نيشان.",
"Coge la barra con las palmas hacia arriba, a la anchura de los hombros.": "شد البارا والكفوف للفوق، على عرض الكتاف.",
"Con el agarre cerrado trabajas más el tríceps que en el press normal.": "بالشدّة المزيّرة كتخدم الترايسبس كثر من البريس العادي.",
"Con las manos abiertas trabajas más la espalda alta y el hombro posterior.": "بالشدّة الكبيرة كتخدم الفوق ديال الضهر واللور ديال الكتف كثر.",
"Con las palmas hacia arriba trabajas más el dorsal bajo y el bíceps.": "بالكفوف للفوق كتخدم التحت ديال الضهر والبايسبس كثر.",
"Con los codos abiertos trabajas más la espalda alta y el hombro posterior.": "بالمرافق للبرا كتخدم الفوق ديال الضهر واللور ديال الكتف كثر.",
"Cuélgate de las asas paralelas con las palmas mirándose.": "تعلّق ف البوانيي المتوازيين والكفوف كيشوفو بعضياتهم.",
"Dominadas (agarre prono)": "Tractions (prise pronation)",
"Dominadas con agarre neutro": "Tractions prise neutre",
"Extensión de tríceps en polea (barra recta)": "Extension des triceps à la poulie (barre droite)",
"Inclina el tronco con la espalda recta y tira de la barra hacia el ombligo.": "ميل للقدام وضهرك نيشان وجبد البارا لجيهة الصرّة.",
"Jalón al pecho (agarre abierto)": "Tirage vertical (prise large)",
"Jalón con agarre estrecho (triángulo)": "Tirage vertical prise serrée (triangle)",
"La foto es con agarre neutro: aquí coge las asas horizontales y lleva los codos abiertos.": "التصويرة فيها شدّة نوترال: هنا، شد البوانيي الأفقيين وخلي المرافق للبرا.",
"La foto es con agarre prono: aquí coge la barra con las palmas hacia arriba.": "التصويرة فيها شدّة برونو: هنا، شد البارا والكفوف للفوق.",
"La foto es con agarre prono: en las neutras coge las asas paralelas, con las palmas mirándose.": "التصويرة فيها شدّة برونو: للشدّة النوترال، شد البوانيي المتوازيين والكفوف كيشوفو بعضياتهم.",
"La foto es con triángulo: aquí usa una barra larga con las manos más abiertas que los hombros.": "التصويرة فيها بارا V: هنا، استعمل بارا طويلة ويديك كبار على كتافك.",
"Polea alta con barra recta, palmas hacia abajo.": "البولي العالية بالبارا نيشان، الكفوف لتحت.",
"Press banca con agarre cerrado": "بانش بريس بشدّة مزيّرة",
