"Siéntate con las rodillas un poco dobladas y coge el triángulo (palmas mirándose).": "گلس وركابيك مطويين شوية وشد البارا V (الكفوف كيشوفو بعضياتهم).",
"Siéntate y coge una barra larga con las palmas hacia abajo, más abierta que los hombros.": "گلس وشد بارا طويلة والكفوف لتحت، كبر من كتافك.",
"Tira con los codos abiertos, a la altura de los hombros.": "جبد والمرافق للبرا، ف علو الكتاف.",
"Tira de las asas llevando los codos atrás, pegados al cuerpo.": "جبد البوانيي وانت كتدّي المرافق للور لاصقين ف جسمك.",
"Tira hacia la parte baja del pecho con los codos abiertos.": "جبد للتحت ديال الصدر والمرافق للبرا.",
"Tira hasta pasar la barbilla por encima de las asas.": "جبد حتى يدوز الدقن فوق البوانيي.",
"Trabaja más bíceps y braquial, y suele molestar menos en los hombros.": "كيخدم البايسبس والبراكيال كثر، وغالبا كيرتّح الكتاف كثر.",
"Túmbate y coge la barra con las manos a la anchura de los hombros.": "تمدد وشد البارا ويديك على عرض الكتاف.",
"Echar el tronco atrás para tirar.": "تميل للور باش تجبد.",
"Juntar demasiado las manos y forzar las muñecas.": "تقرّب يديك بزاف وتفورصي على المعاصم.",
"Barra larga, manos más abiertas que los hombros.": "بارا طويلة، يديك كبار على كتافك.",
"Palmas hacia arriba, manos a la anchura de los hombros.": "الكفوف للفوق، يديك على عرض الكتاف.",
