"ⓘ La foto es con agarre prono: aquí coge la barra con las palmas hacia arriba.": "ⓘ التصويرة فيها شدّة برونو: هنا، شد البارا والكفوف للفوق.",
"ⓘ La foto es con agarre prono: en las neutras coge las asas paralelas, con las palmas mirándose.": "ⓘ التصويرة فيها شدّة برونو: للشدّة النوترال، شد البوانيي المتوازيين والكفوف كيشوفو بعضياتهم.",
