"Remo en T con pecho apoyado": "رامور T-bar والصدر مركّز",
"Túmbate boca abajo en el banco de la máquina de remo en T, con el pecho apoyado.": "تمدد على كرشك ف البانك ديال الماشينة T-bar، والصدر على الكوسان.",
"Coge las asas con los brazos estirados y tira llevando los codos hacia atrás.": "شد البوانيي بدراعاتك ممدودين وجبد وانت كتدّي المرافق للور.",
"Asas abiertas (palmas hacia abajo): más espalda alta. Asas cerradas (palmas mirándose): más dorsal.": "البوانيي الكبار (الكفوف لتحت): الفوق ديال الضهر كثر. البوانيي المزيّرين (الكفوف كيشوفو بعضياتهم): الضهر الجانبي كثر.",
"Ajusta el banco para llegar a las asas con los brazos estirados.": "قاد البانك باش توصل للبوانيي بدراعاتك ممدودين.",
"Elige el agarre: abierto o cerrado.": "ختار الشدّة ديالك: كبيرة ولا مزيّرة.",
"Si te molesta la espalda baja, usa el remo en T con pecho apoyado.": "إلا كان كيضرّك التحت ديال الضهر، استعمل الرامور T-bar والصدر مركّز.",
