"A {n}° trabajas más el pecho alto. Si lo subes a {n}° o más, trabaja más el hombro.": "ف {n}° كتخدم الفوق ديال الصدر كثر. إلا طلعتيه ل {n}° ولا كثر، الكتف كيخدم كثر.",
