"Un entreno más, un paso más cerca.": "حصة أخرى، خطوة أقرب.",
"Descansa bien hoy: mañana vuelves más fuerte.": "ارتاح مزيان اليوم: غدا غادي ترجع أقوى.",
"Una serie más cerca de tu objetivo.": "سيري وحدة أقرب للهدف ديالك.",
"Ni una repetición regalada.": "حتى ريب ما مهدورة.",
"Así se construye el cuerpo que quieres.": "هكا كتبني الجسم اللي بغيتي.",
"Las pesas no se levantan solas.": "الأوزان ما غاديش يطلعو بوحدهم.",
"El sofá te echará de menos. 😏": "الكنبة غادي توحشك. 😏",
"Las mancuernas preguntan por ti. Les he dicho que estabas en el sofá.": "الهالتيرات كيسولو عليك. قلت ليهم راك ف الكنبة.",
"Hoy toca sofá, pero con permiso. 😴": "اليوم نهار الكنبة، ولكن بالإذن. 😴",
