"Jalón con cuerda": "Tirage vertical à la corde",
"Jalón a una mano": "Tirage vertical à un bras",
"Coge las asas paralelas con las palmas mirándose y las manos más abiertas que los hombros.": "شد البوانيي المتوازيين والكفوف كيشوفو بعضياتهم ويديك كبار على كتافك.",
"Tira hasta la parte alta del pecho, con los codos hacia abajo.": "جبد للفوق ديال الصدر، المرافق لتحت.",
"Es más cómodo para los hombros y las muñecas que el agarre abierto.": "كيرتّح الكتاف والمعاصم كثر من الشدّة الكبيرة.",
"Coge la cuerda con una mano a cada lado, palmas mirándose.": "شد الحبل بيد ف كل جيهة، الكفوف كيشوفو بعضياتهم.",
"Tira hacia el pecho y separa las manos al bajar.": "جبد لجيهة الصدر وفرّق يديك ملي كتنزل.",
"Separar las manos abajo te deja llevar los codos más atrás.": "ملي كتفرق يديك ف التحت كتقدر تدّي المرافق للور كثر.",
"Coge el asa con una mano y apoya la otra en el muslo.": "شد البوانيي بيد وحدة وحط الأخرى على فخدك.",
"Tira llevando el codo hacia abajo, pegado al costado.": "جبد وانت كتنزل المرفق، لاصق ف جنبك.",
"Sube despacio hasta estirar el brazo. Luego cambia de lado.": "طلع بشوية حتى يتمد دراعك. ومن بعد بدّل الجيهة.",
"Va genial para igualar un lado de la espalda que esté más flojo.": "مزيان باش تعدّل جيهة من الضهر ضعيفة.",
"Engancha la barra con asas paralelas (las de agarre neutro) a la polea alta.": "ركّب البارا بالبوانيي المتوازيين (ديال الشدّة النوترال) ف البولي العالية.",
"Engancha la cuerda a la polea alta.": "ركّب الحبل ف البولي العالية.",
"Tirar solo con los brazos sin bajar los codos.": "تجبد غير بدراعاتك بلا ما تنزل المرافق.",
"Engancha un asa (estribo) a la polea alta.": "ركّب پوانيي وحدة ف البولي العالية.",
"Agarre neutro ancho": "شدّة نوترال كبيرة",
"Coges las asas paralelas de una barra ancha: las palmas se miran entre sí y las manos van más abiertas que los hombros.": "كتشد البوانيي المتوازيين ديال بارا كبيرة: الكفوف كيشوفو بعضياتهم ويديك كبار على كتافك.",
"Encoger los hombros hacia las orejas al tirar.": "تطلّع كتافك لودنيك ملي كتجبد.",
"Juntar las manos abajo en vez de separarlas.": "تخلي يديك مجموعين ف التحت بلاصة ما تفرقهم.",
"Encoger el hombro del brazo que tira.": "تطلّع الكتف ديال الدراع اللي كيجبد.",
"Remo invertido (australiano)": "Rowing inversé (traction australienne)",
"Cuélgate bajo la barra con el cuerpo recto y los talones en el suelo.": "تعلّق تحت البارا وجسمك نيشان والكعبين ف الأرض.",
"Tira del pecho hacia la barra.": "جبد صدرك لجيهة البارا.",
"Dejar la cadera colgando.": "تخلي الورك يطيح.",
"Cuanto más horizontal estés, más difícil. Escribe {n} kg si no usas lastre.": "كل ما كنتي أفقي كثر، كل ما صعاب. كتب {n} كيلو إلا ما كتستعملش وزن زايد.",
"Encogimientos con barra": "Haussements d'épaules à la barre",
"De pie, con la barra cogida por encima y los brazos estirados.": "وقف وشد البارا من الفوق والدراعات ممدودين.",
"Trabaja el trapecio. Puedes usar correas si se te escapa la barra.": "كيخدم الطرابيز. تقدر تستعمل السانگلات إلا كانت البارا كتزلق.",
"Remo al mentón con barra": "Rowing menton à la barre",
"De pie, con la barra cogida por encima delante de los muslos.": "وقف وشد البارا من الفوق قدام فخدك.",
"Sube la barra pegada al cuerpo llevando los codos por encima de las manos.": "طلّع البارا لاصقة ف جسمك والمرافق فوق اليدين.",
"Subir la barra demasiado alto y forzar el hombro.": "تطلّع البارا عالية بزاف وتفورصي على الكتف.",
"Con las manos algo más abiertas que los hombros es más cómodo.": "مرتاح كثر ويديك كبار شوية على كتافك.",
"Sentadilla frontal": "Squat avant",
"Barra apoyada delante de los hombros, codos altos.": "البارا مركّزة على القدام ديال الكتاف، المرافق عاليين.",
"Baja con el tronco recto, lo más vertical que puedas.": "نزل وجسمك نيشان، واقف على قد ما تقدر.",
"Sube empujando el suelo sin bajar los codos.": "طلع وانت كتدفع الأرض بلا ما تطيّح المرافق.",
"Dejar caer los codos.": "تطيّح المرافق.",
"Trabaja más el cuádriceps y menos la espalda que la sentadilla normal.": "كيخدم الفخد القدامي كثر والضهر قل من السكوات العادي.",
"Peso muerto sumo": "Soulevé de terre sumo",
"Pies muy abiertos y puntas hacia fuera; manos por dentro de las rodillas.": "رجليك محلولين بزاف والصبعين للبرا؛ يديك داخل الركابي.",
"Pecho arriba y espalda recta.": "الصدر للفوق والضهر نيشان.",
"Sube empujando el suelo hacia los lados y extendiendo la cadera.": "طلع وانت كتدفع الأرض للجناب وكتمد الورك.",
"Trabaja más el glúteo y la parte interna del muslo que el peso muerto normal.": "كيخدم الأرداف والداخل ديال الفخد كثر من الديدليفت العادي.",
"Leñador en polea": "Bûcheron à la poulie",
"De lado a la polea alta, coge el asa con las dos manos.": "وقف بالجنب للبولي العالية وشد البوانيي بجوج يديك.",
"Baja en diagonal hacia la rodilla contraria girando el tronco.": "جبد لتحت بالقطر لجيهة الركبة الأخرى وانت كتلوي جسمك.",
"Vuelve despacio. Luego cambia de lado.": "رجع بشوية. ومن بعد بدّل الجيهة.",
"Mover solo los brazos.": "تحرك غير دراعاتك.",
"Trabaja los oblicuos, los abdominales de los lados.": "كيخدم الأوبليك، العضلات ديال البطن اللي ف الجناب.",
"Press Pallof": "Presse Pallof",
"De lado a la polea, con el asa pegada al pecho.": "وقف بالجنب للبولي والبوانيي لاصقة ف صدرك.",
"Estira los brazos hacia delante sin dejar que el cable te gire.": "دفع دراعاتك للقدام بلا ما تخلي الكابل يلويك.",
"Aguanta dos segundos y vuelve. Luego cambia de lado.": "شد جوج ثواني ورجع. ومن بعد بدّل الجيهة.",
"Girar el cuerpo hacia la polea.": "تلوي جسمك لجيهة البولي.",
"El trabajo es aguantar sin girar: así se fortalece el abdomen.": "الخدمة هي تقاوم اللوية: هكا كتقوى البطن.",
"Rotación de tronco": "لوية الجسم",
