"Usa las barras de seguridad del rack a la altura de tu sentadilla.": "حط البارات ديال السيكوريتي ديال الراك ف علو السكوات ديالك.",
"Pies muy abiertos y puntas hacia fuera.": "رجليك محلولين بزاف والصبعين للبرا.",
"Agarra la barra con las manos por dentro de las rodillas.": "شد البارا ويديك داخل الركابي.",
"Dejar que las rodillas se cierren hacia dentro.": "تخلي الركابي يدخلو للداخل.",
"Coge la barra por encima, a la anchura de los hombros.": "شد البارا من الفوق، على عرض الكتاف.",
