"Lo mismo que levantar {n} perros grandes 🐕": "بحال إلا رفعتي {n} كلاب كبار 🐕",
"Tendencia: la media de tus últimos pesos. El peso sube y baja cada día; la tendencia dice la verdad.": "الاتجاه: المتوسط ديال آخر الأوزان ديالك. الوزن كيطلع وكيهبط كل نهار؛ الاتجاه هو اللي كيقول الحقيقة.",
"Pésate al menos {n} veces en {n} semanas (mejor por la mañana) para ver hacia dónde va tu peso.": "توزن على الأقل {n} مرات ف {n} سيمانات (حسن ف الصباح) باش تشوف فين غادي الوزن ديالك.",
"Para ganar masa te conviene subir un poco. Come algo más cada día.": "باش تكسب العضلات خاصك تزيد شوية ف الوزن. كول شوية كثر كل نهار.",
"Subes muy rápido: parte puede ser grasa. Come un poco menos.": "كتزيد بالزربة بزاف: شي حاجة منو يقدر يكون شحم. كول شوية قل.",
"Vas bien: para ganar masa lo ideal es subir entre {n} y {n} kg al mes.": "راك مزيان: باش تكسب العضلات، الأحسن تزيد من {n} ل {n} كيلو ف الشهر.",
"Estás bajando de peso y eso puede frenar tu fuerza. Come un poco más.": "راك كتنقص ف الوزن وهادشي يقدر يفرّن القوة ديالك. كول شوية كثر.",
"Vas bien: para ganar fuerza basta con mantener tu peso o subir poco a poco.": "راك مزيان: باش تولي قوي كثر كافي تحافظ على الوزن ديالك ولا تزيد بشوية.",
"Tu peso cambia bastante rápido. Si no lo buscas, revisa cuánto comes.": "الوزن ديالك كيتبدل بالزربة. إلا ماشي هادا هو الهدف، شوف شحال كتاكل.",
"Tu peso está estable. ¡Sigue así!": "الوزن ديالك مستقر. كمّل هكا!",
