"📲 Consejo: añádela a la pantalla de inicio desde el menú del navegador («Compartir» → «Añadir a pantalla de inicio» en iPhone) y se abrirá como una app.": "📲 نصيحة: زيدها للشاشة الرئيسية من المينو ديال المتصفح («Partager» ← «Sur l'écran d'accueil» ف الآيفون) وغادي تتحل بحال شي أپليكاسيون.",
