"Si pierdes el móvil o se borran los datos del navegador, se pierden. Crea una cuenta gratis y se guardan solos en la nube.": "إلا ضاع ليك التيليفون ولا تمسحات الداتا ديال المتصفح، كيضيعو. دير كونط فابور وغادي يتحفظو بوحدهم ف السحابة.",
