"Antes se llegaba arriba demasiado pronto. Ahora cada rango vale más: Leyenda es nivel de élite. Si has bajado de rango, tu fuerza es la misma; lo que ha cambiado es la vara de medir, y es igual para todos.": "من قبل كان الواحد كيوصل للفوق بالزربة. دابا كل رتبة عندها قيمة كثر: الأسطورة هو مستوى النخبة. إلا هبطتي ف الرتبة، القوة ديالك هي هي؛ اللي تبدل هو الميزان، وهو نفسو للجميع.",
